@triton.autotune(configs=[...], key=['ynumel','xnumel'])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK, XBLOCK):
    yoffset = pid_y * YBLOCK
    while yoffset < ynumel:
        xoffset = pid_x * XBLOCK
        while xoffset < xnumel:
            # same load/store logic
            xoffset += grid_x * XBLOCK
        yoffset += grid_y * YBLOCK

